      assign L0_restart_a0 = L0_reset_a0 || (L0_Crashed_a0 && (Gamepad_start_a0[0] || Gamepad_a_a0[0]));
      assign L0_play_a0 = L0_step_a0 && ! L0_Crashed_a0;
   
      // ---- Falling ----
      // z0, the nearest ring's depth, in 1/16ths. As it passes 16, that ring passes the player ($pass), and
      // the next becomes the nearest. Each level of 512 rings falls faster.
      assign L0_speed_a0[5:0] = 6'd12 + {1'b0, L0_Level_a0, L0_Ring_a0[8:6]};
      assign L0_z_next_a0[10:0] = L0_Depth_a0 - {5'b0, L0_speed_a0};
      assign L0_pass_a0 = L0_z_next_a0 < 11'd256;
      assign L0_Depth_n1[10:0] = L0_restart_a0 ? 11'd1279 : ! L0_play_a0 ? L0_Depth_a0[10:0] : L0_pass_a0 ? L0_z_next_a0 + 11'd1024 : L0_z_next_a0;
      assign L0_z0_a0[15:0] = {9'b0, L0_Depth_a0[10:4]};
      // Rings passed (the depth meter; its low 8 bits identify the nearest ring), and levels completed.
      assign L0_Ring_n1[8:0] = L0_restart_a0 ? 9'd0 : L0_play_a0 && L0_pass_a0 ? L0_Ring_a0 + 9'd1 : L0_Ring_a0[8:0];
      assign L0_Level_n1[1:0] = L0_restart_a0 ? 2'd0 :
                     L0_play_a0 && L0_pass_a0 && L0_Ring_a0 == 9'd511 && L0_Level_a0 != 2'd3 ? L0_Level_a0 + 2'd1 : L0_Level_a0[1:0];
