      assign L0_ph1_a0[7:0] = {L0_n_a0[7:4] + L0_n_a0[3:0] + (L0_x_cyc_a0 ? 4'd0 : 4'd5), L0_n_a0[3:0]};
      assign L0_ph2_a0[7:0] = {L0_n_a0[7:2] + L0_n_a0[5:0] + (L0_x_cyc_a0 ? 6'd16 : 6'd48), L0_n_a0[1:0]};
      assign L0_tri1_a0[6:0] = L0_ph1_a0[7] ? ~L0_ph1_a0[6:0] : L0_ph1_a0[6:0];
      assign L0_tri2_a0[6:0] = L0_ph2_a0[7] ? ~L0_ph2_a0[6:0] : L0_ph2_a0[6:0];
      assign L0_center_a0[10:0] = {{1'b0, L0_tri1_a0, 1'b0} + {2'b0, L0_tri2_a0}, 2'b0};
      assign L0_b_a0[10:0] = L0_center_a0 - (L0_x_cyc_a0 ? Axis_Pos_a0[0] : Axis_Pos_a0[1]);  // b_k.x or b_k.y (signed)
      // V_k, from $Gy = g.y * z0 for the next line.
      assign L0_Gy_n1[15:0] = L0_reset_a0 || (L0_line_end_a0 && L0_Vpos_a0 == 10'd523) ? (L0_z0_a0 << 4) - (L0_z0_a0 << 8) :  // -240 * z0, for line 0
                   L0_line_end_a0 ? L0_Gy_a0 + L0_z0_a0 : L0_Gy_a0[15:0];
      assign L0_gy_a0[11:0] = L0_Vpos_a0 == 10'd524 ? -12'd240 : {2'b0, L0_Vpos_a0} - 12'd239;  // g.y of the next line
      assign L0_gy2k_a0[11:0] = L0_k_a0 == 2'd0 ? 12'd0 :
                    L0_k_a0 == 2'd1 ? L0_gy_a0 << 1 :
                    L0_k_a0 == 2'd2 ? L0_gy_a0 << 2 :
