      // The half-width, sqrt(512^2 - V_k^2) (from a table, for |V_k| / 4), or 0 if the line misses the opening.
      assign L0_u_a0[6:0] = L0_vy_a0[8:2] ^ {7{L0_vy_a0[11]}};  // |V_k| / 4 (about)
