            end
         endfunction
         localparam [128*9-1:0] SQRT_TABLE = sqrt_table();
   
      // ---- Pixels ----
      // S_0 = g.x * z0 / 32, from $Ax = g.x * z0. S_k = S_0 + 2k * g.x, the farther rings' at lower precision
      // (S_1 / 2, S_2 / 8, S_3 / 8), as they need less.
      assign L0_Ax_n1[15:0] = L0_line_end_a0 ? 16'd0 - (L0_z0_a0 << 8) - (L0_z0_a0 << 6) : L0_Ax_a0 + L0_z0_a0;  // From -320 * z0.
      assign L0_gx_a0[11:0] = {2'b0, L0_Hpos_a0} - 12'd320;
      assign L0_s1_a0[11:0] = {{2{L0_Ax_a0[15]}}, L0_Ax_a0[15:6]} + L0_gx_a0;
      assign L0_s2_a0[11:0] = {{4{L0_Ax_a0[15]}}, L0_Ax_a0[15:8]} + {L0_gx_a0[11], L0_gx_a0[11:1]};
      assign L0_s3_a0[11:0] = L0_s2_a0 + {{2{L0_gx_a0[11]}}, L0_gx_a0[11:2]};
      for (ring = 0; ring <= 3; ring++) begin : L1_Ring //_/ring
         assign Ring_write_a0[ring] = L0_span_cyc_a0 && L0_x_cyc_a0 && L0_k_a0 == ring;
         assign Ring_Lo_n1[ring][11:0] = ! Ring_write_a0[ring] ? Ring_Lo_a0[ring][11:0] :
                      ring == 0 ? L0_lo_a0[11:0] : ring == 1 ? L0_lo_a0[12:1] : {{2{L0_lo_a0[12]}}, L0_lo_a0[12:3]};
         assign Ring_Hi_n1[ring][11:0] = ! Ring_write_a0[ring] ? Ring_Hi_a0[ring][11:0] :
                      ring == 0 ? L0_hi_a0[11:0] : ring == 1 ? L0_hi_a0[12:1] : {{2{L0_hi_a0[12]}}, L0_hi_a0[12:3]};
         assign Ring_s_a0[ring][11:0] = ring == 0 ? {L0_Ax_a0[15], L0_Ax_a0[15:5]} : ring == 1 ? L0_s1_a0 : ring == 2 ? L0_s2_a0 : L0_s3_a0;
         // Lo < S < Hi (signed).
         assign Ring_inside_a0[ring] = {~Ring_s_a0[ring][11], Ring_s_a0[ring][10:0]} > {~Ring_Lo_a0[ring][11], Ring_Lo_a0[ring][10:0]} && {~Ring_s_a0[ring][11], Ring_s_a0[ring][10:0]} < {~Ring_Hi_a0[ring][11], Ring_Hi_a0[ring][10:0]};
      end
      // The visible wall (4: the abyss).
      assign L0_wall_a0[2:0] = ! Ring_inside_a0[0] ? 3'd0 : ! Ring_inside_a0[1] ? 3'd1 :
                   ! Ring_inside_a0[2] ? 3'd2 : ! Ring_inside_a0[3] ? 3'd3 : 3'd4;
      // Its shade, lighter as it nears: (272 - z) / 4 for its depth, z, capped at 63; 4 grays (bits 5:4), each
      // dithered toward the next (bits 3:0, against a 4x4 Bayer matrix).
      assign L0_shade_base_a0[6:0] = 7'd68 - {2'b0, L0_Depth_a0[10:6]};
      assign L0_shade_raw_a0[6:0] = L0_shade_base_a0 - {L0_wall_a0[1:0], 4'b0};
      assign L0_shade_a0[5:0] = L0_shade_raw_a0[6] ? 6'd63 : L0_shade_raw_a0[5:0];
      assign L0_bayer_a0[3:0] = {L0_Hpos_a0[0] ^ L0_Vpos_a0[0], L0_Vpos_a0[0], L0_Hpos_a0[1] ^ L0_Vpos_a0[1], L0_Vpos_a0[1]};
      assign L0_gray_a0[1:0] = L0_shade_a0[5:4] + {1'b0, L0_shade_a0[5:4] != 2'd3 && L0_shade_a0[3:0] > L0_bayer_a0};
      // The depth meter, at x 16-31: the rings passed this level (1 pixel each, up to 480), colored by level.
      assign L0_meter_a0 = L0_Hpos_a0[9:4] == 6'd1;
      assign L0_fill_height_a0[8:0] = L0_Ring_a0 - {4'b0, L0_Ring_a0[8:4]};
      assign L0_filled_a0 = {1'b0, L0_Vpos_a0} + {2'b0, L0_fill_height_a0} >= 11'd480;
      assign L0_level_color_a0[5:0] = L0_Level_a0 == 2'd0 ? 6'b00_01_11 :
                          L0_Level_a0 == 2'd1 ? 6'b00_11_01 :
                          L0_Level_a0 == 2'd2 ? 6'b11_11_00 : 6'b11_00_11;
      // Colors (2 bits each of red, green and blue). The pit turns red after a crash.
      assign {R, G, B} =
         L0_meter_a0 ? (L0_filled_a0 ? L0_level_color_a0 : 6'b10_10_10) :
         L0_wall_a0 == 3'd4 ? 6'b00_00_00 :
         L0_Crashed_a0 ? {L0_gray_a0, 4'b0} :
         {L0_gray_a0, L0_gray_a0, L0_gray_a0};
   
      /*
      // Connect Tiny Tapeout outputs
      // Uncomment outputs here, and comment/delete them at the end of this file.
      // (uo_out is driven by tt_vga().)
      *uio_out = 8'b0;
      *uio_oe = 8'b0;
